/**
 * useFacePicker — Vue3 组合式封装 FacePicker class
 *
 * 职责：根据 enabled / obb / faceIndex 响应式驱动 FacePicker 实例的 setup / show /
 * setFaceIndex / hide 生命周期。零业务公式（公式在 facePickingMath），零 store 直接访问
 * （store 的耦合点只在 Viewport 集成层）。
 *
 * <!-- @changelog -->
 * <table>
 *   <tr><th>版本</th><th>变更说明</th><th>关联</th></tr>
 *   <tr>
 *     <td>v1.0.0</td>
 *     <td>骨架创建：useFacePicker 空函数 + watch 占位 + dispose（A-04）</td>
 *     <td>REQ: 20260508-prop正面朝向指定<br/>TECH: 04_design_tech-design.md §3.5.1 (A-04 骨架)</td>
 *   </tr>
 *   <tr>
 *     <td>v1.1.0</td>
 *     <td>
 *       <b>业务实现 (B-06)</b>：
 *       <ul>
 *         <li>watch(enabled)：true 时 trySetup（拿 sdk.getCamera/Scene/DomElement）+ show；false 时 hide</li>
 *         <li>watch(faceIndex)：增量 setFaceIndex（不重建几何）</li>
 *         <li>watch(obb)：obb 引用变化时 hide+show 重建（防御 SDK 重新加载等极端场景，正常 facePicking 期间 OBB 不变）</li>
 *         <li>watch(sdk)：sdk 切换时 hide（防 leak）</li>
 *         <li>onBeforeUnmount：hide + dispose</li>
 *       </ul>
 *     </td>
 *     <td>REQ: 20260508-prop正面朝向指定<br/>TECH: 04_design_tech-design.md §3.5.1 §3.6.2</td>
 *   </tr>
 * </table>
 * <!-- /@changelog -->
 *
 * @author v_djlzhou
 */
import {
  computed,
  onBeforeUnmount,
  watch,
  type ComputedRef,
  type Ref,
  type ShallowRef,
} from 'vue'
import type { ViewerSDK } from '@tencent/viewer-sdk'
import type { SelectionAABB } from '../../stores/scene'
import type { FaceIndex } from '../../utils/facePickingMath'
import { FacePicker } from './face-picker'

export interface UseFacePickerOptions {
  /** 当前活动的 ViewerSDK 引用（来自 Viewport 的 shallowRef）。 */
  sdk: ShallowRef<ViewerSDK | null>
  /** 是否启用：建议绑定 `editorStore.activeTool === 'face-pick'`。 */
  enabled: Ref<boolean> | ComputedRef<boolean>
  /** 当前 OBB 快照（来自 store.pendingFaceOBB）。 */
  obb: Ref<SelectionAABB | null> | ComputedRef<SelectionAABB | null>
  /** 当前选定面索引（来自 store.pendingFaceIndex）。 */
  faceIndex: Ref<FaceIndex | null> | ComputedRef<FaceIndex | null>
  /** 用户切面回调（点击 OBB 某面）。 */
  onFaceChange: (idx: FaceIndex) => void
  /** 用户确认回调（Enter / 双击 / 右键）。 */
  onConfirm: () => void
  /** 用户取消回调（ESC）。 */
  onCancel: () => void
}

export interface UseFacePickerHandle {
  /** FacePicker 是否已就绪（已 show）。 */
  readonly isReady: ComputedRef<boolean>
}

export function useFacePicker(options: UseFacePickerOptions): UseFacePickerHandle {
  let picker: FacePicker | null = null

  const isReady = computed(() => picker !== null)

  /**
   * 尝试创建 FacePicker 实例并 show。
   * 任意依赖未就绪（sdk/obb/faceIndex 缺失）→ 返回 false 让调用方稍后重试。
   */
  function trySetupAndShow(): boolean {
    const sdk = options.sdk.value
    const obb = options.obb.value
    const idx = options.faceIndex.value
    if (!sdk || !obb || idx === null) return false

    const camera = sdk.getCamera()
    const scene = sdk.getScene()
    const domElement = sdk.getDomElement()
    if (!camera || !scene || !domElement) return false

    picker = new FacePicker({
      camera,
      scene,
      domElement,
      onFaceChange: options.onFaceChange,
      onConfirm: options.onConfirm,
      onCancel: options.onCancel,
    })
    picker.show(obb, idx)
    return true
  }

  function teardown(): void {
    picker?.dispose()
    picker = null
  }

  // enabled 切换：true 进入 facePicking、false 退出
  watch(
    () => options.enabled.value,
    (enabled) => {
      if (enabled) {
        if (!picker) trySetupAndShow()
      } else {
        teardown()
      }
    },
    { immediate: true, flush: 'post' },
  )

  // faceIndex 切换：增量更新高亮面（不重建几何）
  watch(
    () => options.faceIndex.value,
    (idx) => {
      if (picker && idx !== null) picker.setFaceIndex(idx)
    },
  )

  // obb 引用变化：重建（正常 facePicking 期间 OBB 不变；切场景等极端情况防御）
  watch(
    () => options.obb.value,
    (obb) => {
      if (!options.enabled.value) return
      if (!obb) {
        teardown()
        return
      }
      // OBB 变化 → 重建（current 实现：完整 hide + show；增量 reshape 留待性能问题暴露后再优化）
      teardown()
      trySetupAndShow()
    },
  )

  // sdk 切换：清理（避免 sdk 引用泄漏）
  watch(
    () => options.sdk.value,
    (sdk, prev) => {
      if (sdk !== prev) teardown()
    },
    { flush: 'sync' },
  )

  onBeforeUnmount(() => {
    teardown()
  })

  return { isReady }
}
