/* ============================================================
 * 基础几何类型（scene-config 领域内独立定义）
 * 理由: 避免与 types/scene.ts 的 Vec3/Bounds 循环引用；
 *      scene-config.json 的 Floor.dimensions 只有 width/depth（无 height），
 *      与 types/scene.ts 的 Dimensions 语义一致但作用域隔离。
 * ============================================================ */

export interface Vec3Config {
  x: number
  y: number
  z: number
}

export interface BoundsConfig {
  minX: number
  maxX: number
  minZ: number
  maxZ: number
  /** Y 维度可选（由点云抽样 p2/p98 分位数计算得到，用于 Front/Side 正交视角） */
  minY?: number
  maxY?: number
}

/* ============================================================
 * PropCategory — 对象分类（CLARIFY Q5 决策: 默认 'decoration'）
 * ============================================================ */

export type PropCategory =
  | 'landmark' // 地标
  | 'furniture' // 家具
  | 'residence' // 住宅
  | 'nature' // 自然
  | 'decoration' // 装饰（默认）
  | 'vehicle' // 交通工具
  | 'building' // 建材
  | 'character' // 角色

/** UI 选项展示用的中文 label 映射 */
export const PROP_CATEGORY_LABELS: Record<PropCategory, string> = {
  landmark: '地标',
  furniture: '家具',
  residence: '住宅',
  nature: '自然',
  decoration: '装饰',
  vehicle: '交通工具',
  building: '建材',
  character: '角色',
}

/** 保持声明顺序的 category 列表，用于 select 渲染 */
export const PROP_CATEGORIES: PropCategory[] = Object.keys(
  PROP_CATEGORY_LABELS,
) as PropCategory[]

/* ============================================================
 * 核心实体类型
 * ============================================================ */

/**
 * 地面标注项。
 * - id / name 必填；description 允许空串但不允许 undefined（CLARIFY Q5 推断）
 * - position.y 默认 0.01（CLARIFY Q5 决策：避免 z-fighting）
 * - dimensions 仅 width / depth（地面无高度）
 * - rotation.y 绕 Y 轴旋转，**单位：度**（[0, 360)，缺省 = 0）
 */
export interface FloorConfigItem {
  id: string
  name: string
  description: string
  type: 'floor'
  position: Vec3Config
  dimensions: { width: number; depth: number }
  rotation?: { y: number }
}

/**
 * 对象标注项。
 * - category 默认 'decoration'（CLARIFY Q5）
 * - rotation.y 归一化到 [0, 360)（CLARIFY Q4，由 store / normalizeRotationY 保证）
 * - rotation.y 直接表达正面朝向（faceIndex × 90° 已折算进去），渲染层蓝色面固定为本地 +Z
 */
export interface PropConfigItem {
  id: string
  name: string
  description: string
  category: PropCategory
  type: 'prop'
  position: Vec3Config
  dimensions: Vec3Config
  rotation: { y: number }
}

/**
 * 场景导出配置顶层结构。
 * 对应 scene-config.json 的完整 schema。
 */
export interface SceneExportConfig {
  sceneId: string
  name: string
  description: string
  bounds: BoundsConfig
  floor: FloorConfigItem[]
  prop: PropConfigItem[]
}

/* ============================================================
 * ID 校验正则（CLARIFY Q3 决策：统一严格 ASCII）
 * 用于 sceneId / floor[i].id / prop[i].id 的字符集校验
 * ============================================================ */

export const ID_REGEX = /^[a-zA-Z][a-zA-Z0-9_]*$/

/* ============================================================
 * 数值规范化工具函数（CLARIFY Q4 决策）
 * 纯函数、无副作用，由 store update action 调用
 * ============================================================ */

/**
 * 数值保留 2 位小数。
 * 用于 position / dimensions / bounds 的所有数值字段。
 */
export function round2(n: number): number {
  return Math.round(n * 100) / 100
}

/**
 * Rotation.y 归一化到 [0, 360)。
 * 允许任意输入（负数 / 大于 360 / 浮点），结果统一到 [0, 360) 且 2 位小数。
 *
 * 示例:
 *   normalizeRotationY(370)  → 10
 *   normalizeRotationY(-30)  → 330
 *   normalizeRotationY(45.5) → 45.5
 */
export function normalizeRotationY(y: number): number {
  const m = ((y % 360) + 360) % 360
  return round2(m)
}

/* ============================================================
 * FaceIndex — 正面索引类型
 * ============================================================ */

/**
 * Prop 正面 4 面索引（OBB 本地系侧面）。
 * 用于 facePicking 流程中选择"哪个面是正面"，commit 时折算进 rotationY。
 */
export type FaceIndex = 0 | 1 | 2 | 3

/* ============================================================
 * 唯一 id 生成（风险盲区 2 防撞号）
 * ============================================================ */

/**
 * 从 existingIds 中找出 {prefix}_N 模式的最大编号 N，返回 {prefix}_{N+1}。
 *
 * 示例:
 *   generateUniqueId('floor', ['floor_1', 'floor_3', 'foo']) → 'floor_4'
 *   generateUniqueId('prop',  [])                             → 'prop_1'
 */
export function generateUniqueId(
  prefix: 'floor' | 'prop',
  existingIds: string[],
): string {
  const re = new RegExp(`^${prefix}_(\\d+)$`)
  let maxN = 0
  for (const id of existingIds) {
    const m = re.exec(id)
    if (m) {
      const n = parseInt(m[1], 10)
      if (!Number.isNaN(n)) maxN = Math.max(maxN, n)
    }
  }
  return `${prefix}_${maxN + 1}`
}

/* ============================================================
 * 默认值工厂（用于「新建」操作）
 * ============================================================ */

/** 创建空场景配置（所有字段初始化为空/默认值）。 */
export function createDefaultSceneConfig(): SceneExportConfig {
  return {
    sceneId: '',
    name: '',
    description: '',
    bounds: { minX: -50, maxX: 50, minZ: -50, maxZ: 50 },
    floor: [],
    prop: [],
  }
}

/**
 * 创建默认 Floor 条目。
 * - id 自动生成（基于现有 ids 计算下一个可用编号）
 * - position.y = 0.01（CLARIFY Q5 决策）
 */
export function createDefaultFloor(existingIds: string[]): FloorConfigItem {
  return {
    id: generateUniqueId('floor', existingIds),
    name: '',
    description: '',
    type: 'floor',
    position: { x: 0, y: 0.01, z: 0 },
    dimensions: { width: 10, depth: 10 },
  }
}

/**
 * 创建默认 Prop 条目。
 * - id 自动生成
 * - category = 'decoration'（CLARIFY Q5 决策）
 */
export function createDefaultProp(existingIds: string[]): PropConfigItem {
  return {
    id: generateUniqueId('prop', existingIds),
    name: '',
    description: '',
    category: 'decoration',
    type: 'prop',
    position: { x: 0, y: 0, z: 0 },
    dimensions: { x: 1, y: 1, z: 1 },
    rotation: { y: 0 },
  }
}
