/**
 * 引导步骤气泡的放置方位。
 */
export type TooltipPlacement = 'top' | 'bottom' | 'left' | 'right' | 'center'

/**
 * 单步引导配置。
 */
export interface OnboardingStep {
  /** 步骤唯一标识 */
  id: string
  /** 目标元素的 CSS 选择器 */
  target: string
  /** 步骤标题 */
  title: string
  /** 步骤说明文案 */
  content: string
  /** 气泡放置方位 */
  placement: TooltipPlacement
  /** 是否为交互验证步骤 */
  interactive?: boolean
  /** interactive=true 时，等待的完成事件名 */
  awaitEvent?: string
}

/**
 * 引导阶段配置。
 *
 * 每个阶段有独立的触发条件，阶段内的步骤线性推进。
 * 阶段之间不强制连续 — 各阶段在对应触发条件满足时独立激活。
 */
export interface OnboardingPhase {
  /** 阶段唯一标识 */
  id: string
  /** 阶段名称（用于帮助菜单/调试） */
  name: string
  /** 触发该阶段的自定义事件名（由业务层 dispatch） */
  triggerEvent: string
  /** 该阶段包含的步骤列表 */
  steps: OnboardingStep[]
}

