/* ============================================================
 * useSceneStore
 * ============================================================ */

export const useSceneStore = defineStore('scene', () => {
  const version = ref('0.1')
  const sceneId = ref('demo_scene')
  const name = ref('Demo Scene')
  const description = ref('A demo scene for UI preview')
  const bounds = ref<Bounds>({ minX: -50, maxX: 50, minZ: -50, maxZ: 50 })
  const objects = ref<SceneObject[]>(mockSceneObjects)
  const selectedObjectId = ref<string | null>(null)

  /* --- 场景管理状态（历史，保留兼容 Mock）--- */
  const metaPath = ref<string | null>(null)
  const sceneMeta = ref<SceneMeta | null>(null)
  const isSceneLoaded = ref(false)
  const isLoading = ref(false)

  /* --- v1.0.0 新增：真实场景加载状态 --- */
  /** 当前已加载的场景 URL（null = 未加载，有值 = 已加载，驱动 Viewport 切换引擎） */
  const sdkSceneUrl = ref<string | null>(null)
  /** 最近使用过的 URL 列表（localStorage 持久化，上限 5 条） */
  const recentUrls = ref<string[]>(loadRecentUrlsSafe())
  /**
   * 最近一次加载的错误（由 Viewport watch 内 sdk.init 失败时回写）。
   * Dialog 通过 await nextTick 观察该字段以决定是否关闭对话框。
   * 设计依据: tech-design.md §3.4.2（SDK 生命周期归属 Viewport 但错误回流）
   */
  const lastLoadError = ref<LoadSceneError | null>(null)

  /* --- v2.0.0 新增：scene-config 编辑数据层 ---
   * 与 objects（只读 meta / Mock）完全隔离的独立数据源（ADR-003）
   * 用户通过 HierarchyPanel「编辑」Tab + InspectorPanel 手动录入
   */

  /** 当前编辑的场景配置（始终存在，初始为空配置） */
  const sceneConfig = ref<SceneExportConfig>(createDefaultSceneConfig())

  /**
   * 可编辑节点的选中态（与 selectedObjectId 互斥，CLARIFY Q1 决策）
   * - null: 未选中
   * - { kind: 'meta' }: 选中场景 Meta 信息行
   * - { kind: 'floor'|'prop', id }: 选中某个 floor/prop 条目
   */
  type SelectedConfigKey =
    | { kind: 'meta' }
    | { kind: 'floor'; id: string }
    | { kind: 'prop'; id: string }
    | null
  const selectedConfigKey = ref<SelectedConfigKey>(null)


  const selectedObject = computed(() =>
    objects.value.find((o) => o.id === selectedObjectId.value) ?? null,
  )

  const objectCount = computed(() => objects.value.length)

  function selectObject(id: string | null) {
    selectedObjectId.value = id
    // v2.0.0: 互斥 — 选中存量 meta/Mock 对象时清空 sceneConfig 的选中态
    if (id !== null) {
      selectedConfigKey.value = null
    }
  }

  function updateObject(id: string, patch: Partial<SceneObject>) {
    const idx = objects.value.findIndex((o) => o.id === id)
    if (idx !== -1) {
      objects.value[idx] = { ...objects.value[idx], ...patch } as SceneObject
    }
  }

  /**
   * @deprecated v1.0.0 起使用 loadSceneFromUrl 替代。本 Mock 方法保留仅为向后兼容。
   * Phase 1 Mock：模拟打开 meta.json 加载场景
   */
  async function loadScene(path: string) {
    isLoading.value = true
    // 模拟异步加载
    await new Promise((r) => setTimeout(r, 600))
    metaPath.value = path
    sceneMeta.value = {
      sceneName: '中式庭院',
      sceneId: 'chinese_courtyard_01',
      splatFile: 'courtyard.splat',
      thumbnail: '',
      description: '中式庭院场景 — 含假山、花坛、石灯笼等元素',
    }
    isSceneLoaded.value = true
    isLoading.value = false
  }

  /**
   * v1.0.0 新增：从 URL 加载真实的 meta.json 并切换到 ViewerSDK 引擎。
   *
   * 采用「成功后一次性提交」模式（tech-design §3.3.1）：
   * - fetch / json 任一失败立即抛 LoadSceneError，store 状态保持不变
   * - 全部成功后才原子赋值 meta / objects / sdkSceneUrl / recentUrls
   *
   * 对话框层调用方式：
   *   try { await store.loadSceneFromUrl(url); await nextTick(); if (!store.lastLoadError) close() }
   *   catch (e) { errorMsg = formatLoadSceneError(e) }
   */
  async function loadSceneFromUrl(url: string): Promise<void> {
    // 1. fetch（分类异常）
    let response: Response
    try {
      response = await fetch(url)
    } catch (e: any) {
      const msg = String(e?.message ?? e ?? '')
      const isCors = /CORS|cross[-\s]?origin|Access-Control/i.test(msg)
      throw new LoadSceneError(
        isCors ? 'CORS_ERROR' : 'NETWORK_ERROR',
        msg || '网络请求失败',
        e,
      )
    }

    // 2. HTTP 状态
    if (!response.ok) {
      throw new LoadSceneError('HTTP_ERROR', `URL 不可达（HTTP ${response.status}）`)
    }

    // 3. JSON 解析
    let meta: SceneMeta
    try {
      meta = (await response.json()) as SceneMeta
    } catch (e) {
      throw new LoadSceneError('JSON_PARSE_ERROR', 'URL 返回内容不是合法 JSON', e)
    }

    // 4. 原子提交（成功后一次性赋值）
    sceneMeta.value = meta
    objects.value = parseMetaToObjects(meta)
    metaPath.value = url
    isSceneLoaded.value = true
    isLoading.value = false
    sdkSceneUrl.value = url
    lastLoadError.value = null
    pushRecentUrl(url)
  }

  /**
   * 卸载当前场景，回到本地栅格占位状态。
   *
   * v3.4.0：除了清高斯场景维度（meta/sdkSceneUrl/objects），还要复位 sceneConfig。
   * 否则 floor/prop 坐标会残留到下次加载，与新底图坐标系完全不匹配，
   * 用户会看到"幽灵标注"漂在新场景里 —— 数据脏态。
   * replaceSceneConfig 的副作用（清 selectedConfigKey / selectedObjectId /
   * pendingSelection / pendingCreateKind）正好对齐"卸载即归零"的语义需求。
   */
  function unloadScene() {
    const prevSceneUrl = sdkSceneUrl.value // 暂存：清零后仍需用于草稿清理
    metaPath.value = null
    sceneMeta.value = null
    isSceneLoaded.value = false
    sdkSceneUrl.value = null
    objects.value = mockSceneObjects // 回到 Mock 占位（保持原有 UI 行为）
    // v3.4.0：sceneConfig 与高斯场景同生命周期，必须一起清；
    //        replaceSceneConfig 内部已处理选中态 / 框选态 / 创建意图的清理
    replaceSceneConfig(createDefaultSceneConfig())
    // v4.2.0：bounds 计算反馈也是单场景生命周期内的临时状态
    lastBoundsComputeStatus.value = null
    // v7.0.0：草稿随场景卸载一并清理（旧场景草稿与新场景无关，不应残留）
    if (prevSceneUrl) clearDraftStorage(prevSceneUrl)
    lastDraftSavedAt.value = null
    // 注意：不清 recentUrls（那是历史记录，不应因卸载而丢失）
    // 注意：不清 lastLoadError（由调用方主动清理，以保证 Dialog 能读到错误）
  }

  /**
   * 把 URL 推入最近使用列表：去重 + 置顶 + 截断到 5 条 + 持久化。
   * localStorage 写入失败时仅内存维护（隐私模式兼容）。
   */
  function pushRecentUrl(url: string) {
    const filtered = recentUrls.value.filter((u) => u !== url)
    const next = [url, ...filtered].slice(0, RECENT_URLS_MAX)
    recentUrls.value = next
    saveRecentUrlsSafe(next)
  }

  /* ============================================================
   * v2.0.0: scene-config CRUD actions
   * 所有数值字段由 store 内部做 round2 / normalizeRotationY 规范化，
   * 避免 UI 层重复实现（CLARIFY Q4 决策）
   * ============================================================ */

  /** 互斥选中：可编辑节点选中 → 清空 selectedObjectId（CLARIFY Q1） */
  function selectConfig(key: Exclude<SelectedConfigKey, null>): void {
    selectedConfigKey.value = key
    selectedObjectId.value = null
  }

  /** 互斥选中：只读 meta 节点选中 → 清空 selectedConfigKey（CLARIFY Q1） */
  function selectMetaNode(id: string): void {
    selectedObjectId.value = id
    selectedConfigKey.value = null
  }

  /** 清空所有选中态 */
  function clearSelection(): void {
    selectedConfigKey.value = null
    selectedObjectId.value = null
  }

  /** 汇总当前场景内所有 id（floor ∪ prop），用于新建时去重 */
  function collectAllIds(): string[] {
    return [
      ...sceneConfig.value.floor.map((f) => f.id),
      ...sceneConfig.value.prop.map((p) => p.id),
    ]
  }

  /* ============================================================
   * v6.0.0: 受控 Snapshot API（撤销 / 重做基础设施）
   *
   * 这些 API 是 Command 对象与 store 之间的唯一桥梁。
   * 所有 snapshot 写入仍经过 round2 / normalizeRotationY 规范化。
   * Command 不直接操作 sceneConfig.floor/prop 数组。
   * ============================================================ */

  /**
   * 深拷贝规范化一个 FloorConfigItem。
   * 保证与 updateFloor 相同的 round2 + normalizeRotationY 口径。
   */
  function normalizeFloor(f: FloorConfigItem): FloorConfigItem {
    return {
      id: f.id,
      name: f.name,
      description: f.description,
      type: 'floor',
      position: {
        x: round2(f.position.x),
        y: round2(f.position.y),
        z: round2(f.position.z),
      },
      dimensions: {
        width: round2(f.dimensions.width),
        depth: round2(f.dimensions.depth),
      },
      ...(f.rotation ? { rotation: { y: normalizeRotationY(f.rotation.y) } } : {}),
    }
  }

  /**
   * 深拷贝规范化一个 PropConfigItem。
   */
  function normalizeProp(p: PropConfigItem): PropConfigItem {
    return {
      id: p.id,
      name: p.name,
      description: p.description,
      category: p.category,
      type: 'prop',
      position: {
        x: round2(p.position.x),
        y: round2(p.position.y),
        z: round2(p.position.z),
      },
      dimensions: {
        x: round2(p.dimensions.x),
        y: round2(p.dimensions.y),
        z: round2(p.dimensions.z),
      },
      rotation: { y: normalizeRotationY(p.rotation.y) },
    }
  }

  /** 获取 floor 深拷贝快照（不存在返回 null） */
  function getFloorSnapshot(id: string): FloorConfigItem | null {
    const f = sceneConfig.value.floor.find((item) => item.id === id)
    if (!f) return null
    return normalizeFloor(f)
  }

  /** 获取 prop 深拷贝快照（不存在返回 null） */
  function getPropSnapshot(id: string): PropConfigItem | null {
    const p = sceneConfig.value.prop.find((item) => item.id === id)
    if (!p) return null
    return normalizeProp(p)
  }

  /**
   * 受控插入 Floor（深拷贝 + 规范化 + ID 冲突检查）。
   * @returns true = 插入成功；false = ID 冲突
   */
  function insertFloorSnapshot(item: FloorConfigItem, opts?: InsertOptions): boolean {
    // ID 冲突检查
    if (collectAllIds().includes(item.id)) return false

    const normalized = normalizeFloor(item)
    sceneConfig.value.floor.push(normalized)

    if (opts?.select) {
      selectConfig({ kind: 'floor', id: normalized.id })
    }
    return true
  }

  /**
   * 受控插入 Prop（深拷贝 + 规范化 + ID 冲突检查）。
   * @returns true = 插入成功；false = ID 冲突
   */
  function insertPropSnapshot(item: PropConfigItem, opts?: InsertOptions): boolean {
    if (collectAllIds().includes(item.id)) return false

    const normalized = normalizeProp(item)
    sceneConfig.value.prop.push(normalized)

    if (opts?.select) {
      selectConfig({ kind: 'prop', id: normalized.id })
    }
    return true
  }

  /**
   * 按 targetId 定位并整体替换为 next（支持 id 变更）。
   * @returns true = 替换成功；false = 找不到目标
   */
  function replaceFloorSnapshot(targetId: string, next: FloorConfigItem): boolean {
    const idx = sceneConfig.value.floor.findIndex((f) => f.id === targetId)
    if (idx === -1) return false

    const normalized = normalizeFloor(next)
    sceneConfig.value.floor[idx] = normalized

    // 如果 id 发生变化，且旧 id 是当前选中项，更新选中态
    if (
      selectedConfigKey.value?.kind === 'floor' &&
      selectedConfigKey.value.id === targetId &&
      targetId !== normalized.id
    ) {
      selectedConfigKey.value = { kind: 'floor', id: normalized.id }
    }

    return true
  }

  /**
   * 按 targetId 定位并整体替换为 next（支持 id 变更）。
   * @returns true = 替换成功；false = 找不到目标
   */
  function replacePropSnapshot(targetId: string, next: PropConfigItem): boolean {
    const idx = sceneConfig.value.prop.findIndex((p) => p.id === targetId)
    if (idx === -1) return false

    const normalized = normalizeProp(next)
    sceneConfig.value.prop[idx] = normalized

    if (
      selectedConfigKey.value?.kind === 'prop' &&
      selectedConfigKey.value.id === targetId &&
      targetId !== normalized.id
    ) {
      selectedConfigKey.value = { kind: 'prop', id: normalized.id }
    }

    return true
  }

  /**
   * 删除 Floor 并返回被删快照（Command 可缓存用于 undo）。
   * 若删除的是选中项则清空选中态。
   * @returns 被删对象快照；找不到返回 null
   */
  function removeFloorById(id: string): FloorConfigItem | null {
    const idx = sceneConfig.value.floor.findIndex((f) => f.id === id)
    if (idx === -1) return null

    const removed = normalizeFloor(sceneConfig.value.floor[idx])
    sceneConfig.value.floor.splice(idx, 1)

    if (
      selectedConfigKey.value?.kind === 'floor' &&
      selectedConfigKey.value.id === id
    ) {
      clearSelection()
    }

    return removed
  }

  /**
   * 删除 Prop 并返回被删快照。
   * @returns 被删对象快照；找不到返回 null
   */
  function removePropById(id: string): PropConfigItem | null {
    const idx = sceneConfig.value.prop.findIndex((p) => p.id === id)
    if (idx === -1) return null

    const removed = normalizeProp(sceneConfig.value.prop[idx])
    sceneConfig.value.prop.splice(idx, 1)

    if (
      selectedConfigKey.value?.kind === 'prop' &&
      selectedConfigKey.value.id === id
    ) {
      clearSelection()
    }

    return removed
  }

  /** 更新 Meta 信息（sceneId/name/description/bounds），bounds 内部 round2 */
  function updateSceneMeta(
    patch: Partial<Pick<SceneExportConfig, 'sceneId' | 'name' | 'description' | 'bounds'>>,
  ): void {
    const next: Partial<SceneExportConfig> = { ...patch }
    if (patch.bounds) {
      const b: BoundsConfig = {
        minX: round2(patch.bounds.minX),
        maxX: round2(patch.bounds.maxX),
        minZ: round2(patch.bounds.minZ),
        maxZ: round2(patch.bounds.maxZ),
      }
      // Y 维度可选：由点云抽样计算得到，供正交相机 Front/Side 视角使用
      if (patch.bounds.minY != null) b.minY = round2(patch.bounds.minY)
      if (patch.bounds.maxY != null) b.maxY = round2(patch.bounds.maxY)
      next.bounds = b
    }
    sceneConfig.value = { ...sceneConfig.value, ...next }
  }

  /**
   * 整体替换 sceneConfig（v3.3.0）。
   *
   * 唯一允许从外部"批量写入整份配置"的入口；用于导入 scene-config.json。
   * 调用前调用方需自行完成解析 + 校验（utils/sceneConfigImporter）。
   *
   * 副作用：
   *   · 清空 selectedConfigKey（旧选中 id 在新配置里大概率不存在）
   *   · 清空 pendingSelection / pendingCreateKind（避免新旧数据混合的脏态）
   *
   * 不做的事：
   *   · 不做校验（信任调用方已做 validateSceneConfig）
   *   · 不做 normalizeRotationY / round2（信任 importer 已规范化）
   *   · 不动 sdkSceneUrl / sceneMeta（scene-config 与高斯泼溅 meta 是两个独立维度）
   */
  function replaceSceneConfig(next: SceneExportConfig): void {
    sceneConfig.value = next
    selectedConfigKey.value = null
    selectedObjectId.value = null
    pendingSelection.value = null
    pendingCreateKind.value = null
  }


  /** 新建 Floor 条目，自动生成唯一 id 并选中 */
  function addFloor(): FloorConfigItem {
    const f = createDefaultFloor(collectAllIds())
    sceneConfig.value.floor.push(f)
    selectConfig({ kind: 'floor', id: f.id })
    return f
  }

  /** 更新 Floor 条目；position/dimensions 内部 round2；rotation.y 归一化 */
  function updateFloor(id: string, patch: Partial<FloorConfigItem>): void {
    const idx = sceneConfig.value.floor.findIndex((f) => f.id === id)
    if (idx === -1) return

    const normalized: Partial<FloorConfigItem> = { ...patch }
    if (patch.position) {
      normalized.position = {
        x: round2(patch.position.x),
        y: round2(patch.position.y),
        z: round2(patch.position.z),
      }
    }
    if (patch.dimensions) {
      normalized.dimensions = {
        width: round2(patch.dimensions.width),
        depth: round2(patch.dimensions.depth),
      }
    }
    if (patch.rotation) {
      normalized.rotation = { y: normalizeRotationY(patch.rotation.y) }
    }
    sceneConfig.value.floor[idx] = {
      ...sceneConfig.value.floor[idx],
      ...normalized,
    }
  }

  /** 删除 Floor 条目；若删除的是选中项则清空选中态（RISK-DA002 mitigation） */
  function removeFloor(id: string): void {
    sceneConfig.value.floor = sceneConfig.value.floor.filter((f) => f.id !== id)
    if (
      selectedConfigKey.value?.kind === 'floor' &&
      selectedConfigKey.value.id === id
    ) {
      clearSelection()
    }
  }

  /** 新建 Prop 条目 */
  function addProp(): PropConfigItem {
    const p = createDefaultProp(collectAllIds())
    sceneConfig.value.prop.push(p)
    selectConfig({ kind: 'prop', id: p.id })
    return p
  }

  /** 更新 Prop 条目；position/dimensions round2；rotation.y 归一化 */
  function updateProp(id: string, patch: Partial<PropConfigItem>): void {
    const idx = sceneConfig.value.prop.findIndex((p) => p.id === id)
    if (idx === -1) return

    const normalized: Partial<PropConfigItem> = { ...patch }
    if (patch.position) {
      normalized.position = {
        x: round2(patch.position.x),
        y: round2(patch.position.y),
        z: round2(patch.position.z),
      }
    }
    if (patch.dimensions) {
      normalized.dimensions = {
        x: round2(patch.dimensions.x),
        y: round2(patch.dimensions.y),
        z: round2(patch.dimensions.z),
      }
    }
    if (patch.rotation) {
      normalized.rotation = { y: normalizeRotationY(patch.rotation.y) }
    }
    sceneConfig.value.prop[idx] = {
      ...sceneConfig.value.prop[idx],
      ...normalized,
    }
  }

  /** 删除 Prop 条目；悬空引用清理 */
  function removeProp(id: string): void {
    sceneConfig.value.prop = sceneConfig.value.prop.filter((p) => p.id !== id)
    if (
      selectedConfigKey.value?.kind === 'prop' &&
      selectedConfigKey.value.id === id
    ) {
      clearSelection()
    }
  }

  /* --- v2.0.0 getters --- */

  /** 导出按钮可用条件（CLARIFY Q2）：sceneId 非空 或 floor/prop 非空 */
  const canExportConfig = computed<boolean>(
    () =>
      sceneConfig.value.sceneId !== '' ||
      sceneConfig.value.floor.length > 0 ||
      sceneConfig.value.prop.length > 0,
  )

  /** 实时校验错误（导出前检查） */
  const configValidationErrors = computed(() =>
    validateSceneConfig(sceneConfig.value),
  )

  /* --- v3.0.0 新增：框选标注流程 --- */

  /** 待标注的选区（null = 无待标注） */
  const pendingSelection = ref<SelectionAABB | null>(null)

  /** 是否有待标注的选区 */
  const hasPendingSelection = computed(() => pendingSelection.value !== null)

  /** 设置待标注选区（由 SelectionBridge 回调写入） */
  function setPendingSelection(aabb: SelectionAABB | null): void {
    pendingSelection.value = aabb
    if (aabb) {
      // OP-7: 有 Unlabeled 选区时自动显示 InspectorPanel
      const panelsStore = usePanelsStore()
      panelsStore.setVisibility('inspector', true)
    }
  }

  /** 将待标注选区提交为 Floor */
  function commitPendingAsFloor(): void {
    if (!pendingSelection.value) return
    const aabb = pendingSelection.value
    const id = generateUniqueId('floor', collectAllIds())
    // minY = anchorY - AABB_HEIGHT_BELOW（SelectionManager 写入），贴实际碰撞表面
    const posY = aabb.minY != null ? round2(aabb.minY) : 0.01
    const floor: FloorConfigItem = {
      id,
      name: '',
      description: '',
      type: 'floor',
      position: {
        x: round2((aabb.minX + aabb.maxX) / 2),
        y: posY,
        z: round2((aabb.minZ + aabb.maxZ) / 2),
      },
      dimensions: {
        width: round2(aabb.maxX - aabb.minX),
        depth: round2(aabb.maxZ - aabb.minZ),
      },
      rotation: { y: round2((aabb.rotationY ?? 0) * (180 / Math.PI)) },
    }
    sceneConfig.value.floor.push(floor)
    selectConfig({ kind: 'floor', id })
    pendingSelection.value = null
  }

  /** 将待标注选区提交为 Prop */
  function commitPendingAsProp(): void {
    if (!pendingSelection.value) return
    const aabb = pendingSelection.value
    const id = generateUniqueId('prop', collectAllIds())
    // minY 为底面 Y（贴碰撞表面），maxY - minY 为拖框高度；无 Y 信息时用默认值
    const posY = aabb.minY != null ? round2(aabb.minY) : 0
    const dimY =
      aabb.minY != null && aabb.maxY != null
        ? round2(aabb.maxY - aabb.minY)
        : 1
    // v5.0.0：rotationY = OBB 朝向 + faceIndex × 90°，一步到位表达正面方向。
    //   当 faceIndex 为奇数（1/3）时正面从 Z 面切到 X 面，需交换 dimensions.x/z，
    //   确保 dimensions.x 始终是正面宽度、dimensions.z 始终是侧面深度。
    const obbDeg = (aabb.rotationY ?? 0) * (180 / Math.PI)
    const faceIdx: FaceIndex = pendingFaceIndex.value ?? 0
    const rotYDeg = normalizeRotationY(obbDeg + faceIdx * 90)
    const rawDimX = round2(aabb.maxX - aabb.minX)
    const rawDimZ = round2(aabb.maxZ - aabb.minZ)
    // 奇数 faceIndex（+X 或 -X 面作为正面）：交换 x/z 维度
    const swapXZ = faceIdx === 1 || faceIdx === 3
    const prop: PropConfigItem = {
      id,
      name: '',
      description: '',
      category: 'decoration',
      type: 'prop',
      position: {
        x: round2((aabb.minX + aabb.maxX) / 2),
        y: posY,
        z: round2((aabb.minZ + aabb.maxZ) / 2),
      },
      dimensions: {
        x: swapXZ ? rawDimZ : rawDimX,
        y: dimY,
        z: swapXZ ? rawDimX : rawDimZ,
      },
      rotation: { y: rotYDeg },
    }
    sceneConfig.value.prop.push(prop)
    selectConfig({ kind: 'prop', id })
    pendingSelection.value = null
  }

  /** 丢弃待标注选区 */
  function discardPendingSelection(): void {
    pendingSelection.value = null
  }

  /**
   * 取消选区信号（递增 tick，Viewport 监听后调 SDK SelectionManager.cancelSelection()）。
   *
   * 为什么需要独立信号（而非复用 pendingSelection 置空的 watch）：
   *   dragging 态下 pendingSelection 还未写入（只有 committed 后才写），此时 ESC
   *   再赋 null 是"同值赋值"，Vue watch 默认不触发，无法打断 SDK 的 dragging。
   *   用独立的递增 tick 信号确保每次请求都能触达 SDK。
   */
  const cancelSelectionTick = ref(0)

  /**
   * 请求取消当前框选（ESC / 工具切换 / Dialog 打开 / 再次点击入口 等场景）。
   *
   * 效果覆盖三类态：
   *   - committed：pendingSelection = null → watch 链路清状态（Inspector 等）
   *   - dragging：通过 cancelSelectionTick 递增触发 Viewport 调用本地 useSelection.cancelSelection()
   *   - 创建意图：pendingCreateKind = null（v4.0.0 新增，RISK-DS002 mitigation）
   */
  function requestCancelSelection(): void {
    pendingSelection.value = null
    cancelSelectionTick.value++
    pendingCreateKind.value = null
  }

  /**
   * 仅取消当前框选动作，**不清 pendingCreateKind**。
   *
   * 语义：用户只是取消了本次拖拽框选，创建意图（新增地面/对象）仍然有效。
   * 适用场景：ESC 第一档（拖拽中取消框选），面板 CTA 应保持"框选中…"态，
   * 让用户可以立即重新拖选。
   *
   * 与 requestCancelSelection 的区别：不清 pendingCreateKind。
   */
  function cancelSelectionOnly(): void {
    pendingSelection.value = null
    cancelSelectionTick.value++
  }


  /**
   * SDK SelectionManager 是否处于 dragging 态。
   *
   * 注意：它只镜像「正在拖拽」这一瞬时状态，不代表 committed；
   * committed 选区是否存在，仍以 pendingSelection 是否为 null 为准。
   *
   * 用途：为宿主 ESC 双档语义提供 dragging 判定，并在 teardown 后显式归零。
   * 由 Viewport 通过 H5 本地 useSelection 的 onStateChange 回调反射而来，宿主只读。

   */
  const isSelectionDragging = ref(false)

  function setSelectionDragging(dragging: boolean): void {
    isSelectionDragging.value = dragging
  }

  /* ============================================================
   * v4.0.0 新增：创建驱动标注流程（REQ 20260427，ADR-001/002）
   *
   * 设计要点：
   * 1. pendingCreateKind 是"用户意图"的单一真相源
   * 2. 入口 = startCreateFloor/Prop（只由 HierarchyPanel 触发）
   * 3. 出口 = Viewport 的 watch(pendingSelection) 分支（自动 commit）
   *        或 requestCancelSelection()（ESC/Dialog/再次点击撤销/工具切换）
   *        或 Viewport.teardownViewerSDK 的兜底清理
   * ============================================================ */

  /** 当前创建意图（null = 无意图） */
  const pendingCreateKind = ref<PendingCreateKind>(null)

  /**
   * 开始创建地面：记录意图 + 激活 region-select 工具。
   *
   * 守护链：
   *   1. 场景未加载 → no-op（UI 按钮已禁用，此处做防御性编程，RISK-DS005 mitigation）
   *   2. 先 discardPendingSelection()，避免意图覆盖场景下有残留选区（RISK-DS006 mitigation）
   *   3. 直接覆盖旧意图（允许 Floor → Prop / Prop → Floor 切换）
   *
   * @see 04_design_tech-design.md §3.2.2 + §3.4.1
   */
  function startCreateFloor(): void {
    if (!sdkSceneUrl.value) return
    discardPendingSelection()
    pendingCreateKind.value = 'floor'
    useEditorStore().setTool('region-select')
  }

  /** 开始创建对象（Prop），规则同 startCreateFloor */
  function startCreateProp(): void {
    if (!sdkSceneUrl.value) return
    discardPendingSelection()
    pendingCreateKind.value = 'prop'
    useEditorStore().setTool('region-select')
  }

  /** 清空创建意图（供 Viewport watch 分支自动 commit 后调用） */
  function clearPendingCreateKind(): void {
    pendingCreateKind.value = null
  }

  /* ============================================================
   * v4.1.0 新增：双击层级行 → 相机聚焦目标
   *
   * 设计要点：
   * 1. 复用「tick 信号 + 目标载荷」的成熟模式（同 cancelSelectionTick）
   *    避免双击同一项时同值赋值不触发 watch
   * 2. focusRequest 仅承载"聚焦谁"，相机如何摆放（距离/角度）由 Viewport 计算
   * 3. 调用方语义：focusOnFloor/Prop = 选中 + 聚焦（双击 = 单击的超集）
   * ============================================================ */

  /** 聚焦请求目标（最新一次双击的 floor/prop） */
  const focusRequest = ref<{ kind: 'floor' | 'prop'; id: string } | null>(null)

  /** 聚焦请求计数器（递增触发 Viewport watch） */
  const focusRequestTick = ref(0)

  /**
   * 请求相机聚焦到指定 floor。
   * 同步副作用：
   *  - 选中该 floor（与单击行为一致，保证选中态高亮 / Inspector 数据同步）
   *  - 递增 focusRequestTick → Viewport 监听后驱动 FlyCameraController
   */
  function focusOnFloor(id: string): void {
    selectConfig({ kind: 'floor', id })
    focusRequest.value = { kind: 'floor', id }
    focusRequestTick.value++
  }

  /** 请求相机聚焦到指定 prop（行为对称 focusOnFloor） */
  function focusOnProp(id: string): void {
    selectConfig({ kind: 'prop', id })
    focusRequest.value = { kind: 'prop', id }
    focusRequestTick.value++
  }

  /* ============================================================
   * v4.2.0 新增：bounds 自动回填（场景边界从 SDK 实际加载场景计算）
   *
   * 设计要点（取舍 1 = 方案 D）：
   * 1. 自动路径仅在"用户尚未编辑过 bounds"时生效，保护用户手填值
   *    判定标准 = 当前 bounds 完全等于 createDefaultSceneConfig() 的默认值
   * 2. 强制路径供 InspectorPanel 的"↻ 从场景重新计算"按钮兜底
   * 3. 两个入口都委托给 updateSceneMeta：复用 round2 规范化路径，
   *    保证与"手填 → updateSceneMeta"产物完全一致；不绕开数据契约
   * 4. 入参为 BoundsConfig（已经过 round2 + 解 worldOffset）；
   *    本 store 不再 import SDK 类型，避免反向依赖 viewer-sdk
   * ============================================================ */

  /**
   * 仅当 bounds 仍是默认值（-50/50/-50/50）时，才用 next 覆盖。
   * 用于"加载新场景 ready 后自动回填"链路。
   *
   * @returns true = 已覆盖；false = 因用户已编辑而保留
   */
  function applyAutoBoundsIfDefault(next: BoundsConfig): boolean {
    const cur = sceneConfig.value.bounds
    const isDefault =
      cur.minX === -50 &&
      cur.maxX === 50 &&
      cur.minZ === -50 &&
      cur.maxZ === 50
    if (!isDefault) return false
    updateSceneMeta({ bounds: next })
    return true
  }

  /**
   * 强制用 next 覆盖 bounds（不做默认值判断）。
   * 用于 InspectorPanel 的"从场景重新计算"按钮：用户主动按 = 明确意图。
   */
  function applyAutoBoundsForce(next: BoundsConfig): void {
    updateSceneMeta({ bounds: next })
  }

  /**
   * "从场景重新计算 bounds" 信号 tick。
   * 递增 → Viewport watch → 调 computeSceneBoundsFromSdk(sdk) → applyAutoBoundsForce
   *
   * 为什么不让 store 直接算：
   *   store 不持有 ViewerSDK 实例（实例由 Viewport 局部 shallowRef 管理），
   *   且 store 不应反向依赖 viewer-sdk。把"算"留给 Viewport，把"存"留给 store。
   */
  const recomputeBoundsTick = ref(0)

  /** 请求从当前已加载的 SDK 场景重新计算 bounds（强制覆盖）。 */
  function requestRecomputeBounds(): void {
    recomputeBoundsTick.value++
  }

  /* ----- v4.2.0：bounds 计算反馈状态（成功源 / 失败原因） -----
   * Viewport 算完后调 setLastBoundsComputeStatus 把结果通知 UI（InspectorPanel）。
   * - ok = true  : 显示一行 success 提示（含 source = region-modules / single-scene-aabb）
   * - ok = false : 显示 warn 提示 + 中文 reason，便于用户/排查者定位"哪一步算不出"
   * 设计为"上次状态"模型：每次按钮按下都会覆盖；切场景时清空（unloadScene 里 reset）。
   */
  type BoundsComputeStatus =
    | { ok: true; source: string; hitCount: number; ts: number }
    | { ok: false; reason: string; message: string; ts: number }
  const lastBoundsComputeStatus = ref<BoundsComputeStatus | null>(null)

  function setLastBoundsComputeStatus(
    s:
      | { ok: true; source: string; hitCount: number }
      | { ok: false; reason: string; message: string },
  ): void {
    lastBoundsComputeStatus.value = { ...s, ts: Date.now() } as BoundsComputeStatus
  }

  function clearLastBoundsComputeStatus(): void {
    lastBoundsComputeStatus.value = null
  }

  /* ============================================================
   * v4.7.0 新增：Prop 正面朝向指定（facePicking 中间态）
   *
   * 设计要点（REQ 20260508，tech-design §3.2.2 + ADR-002 + CL-1..4）：
   * 1. pendingFaceOBB 是 pendingSelection 的【快照】（值拷贝），不是响应式别名
   *    避免 EV-012 多通路数据契约破裂
   * 2. defaultFaceIndex 在进入瞬间计算一次后锁定（CL-2）
   * 3. confirmPropFace 单事务：commit → 清 face → 清 createKind → setTool('move')
   * 4. cancelFacePicking（ESC）：丢 face + selection，保留 pendingCreateKind（CL-4 区分）
   * 5. clearFacePicking：通用清理（仅 face state）
   * ============================================================ */

  /**
   * facePicking 期间使用的 OBB 快照（pendingSelection 的值拷贝，ADR-002）。
   * 用快照原因：pendingSelection 可能被并发路径清空，FacePicker 渲染需稳定数据源。
   */
  const pendingFaceOBB = ref<SelectionAABB | null>(null)

  /** 当前选定的正面索引（0..3），null = 不在 facePicking 态。 */
  const pendingFaceIndex = ref<FaceIndex | null>(null)

  /**
   * 进入 facePicking 中间态。调用方：Viewport.watch(pendingSelection) prop 分支。
   * 副作用：浅快照 OBB → 写 faceIndex → setTool('face-pick')。
   * 注意：不清 pendingSelection —— commit 时仍需读 dimensions/position。
   */
  function enterFacePicking(defaultFaceIndex: FaceIndex): void {
    if (!pendingSelection.value) return
    pendingFaceOBB.value = { ...pendingSelection.value }
    pendingFaceIndex.value = defaultFaceIndex
    useEditorStore().setTool('face-pick')
  }

  /** 用户左键点击 OBB 某面 → 切换正面索引（FacePicker 通过 watch 同步高亮）。 */
  function setPendingFaceIndex(idx: FaceIndex): void {
    if (pendingFaceOBB.value === null) return
    pendingFaceIndex.value = idx
  }

  /** 仅清理 facePicking state（不动 pendingSelection / pendingCreateKind / activeTool）。 */
  function clearFacePicking(): void {
    pendingFaceOBB.value = null
    pendingFaceIndex.value = null
  }

  /**
   * 用户确认正面，提交 prop 并落地到 'move' 工具（事务，ADR-005）。
   * commitPendingAsProp 内部读 pendingFaceIndex 自动应用公式（单一事实源）。
   */
  function confirmPropFace(): void {
    if (pendingFaceOBB.value === null || pendingFaceIndex.value === null) return
    commitPendingAsProp()
    clearFacePicking()
    pendingCreateKind.value = null
    useEditorStore().setTool('move')
  }

  /**
   * 用户 ESC 取消 facePicking，回到 region-select 等待重新框选（CL-4 保留 pendingCreateKind）。
   * cancelSelectionTick++ 对齐 cancelSelectionOnly 模式，让 useSelection 清掉本地 dragging 残留。
   */
  function cancelFacePicking(): void {
    clearFacePicking()
    pendingSelection.value = null
    cancelSelectionTick.value++
    useEditorStore().setTool('region-select')
  }

  /* ============================================================
   * v7.0.0 新增：标注草稿自动存档
   *
   * 设计要点：
   *   · store 只持有「最后存档时间」和两个原子 action
   *   · 存储实现全部委托给 utils/draftStorage.ts（Safe 模式，静默失败）
   *   · watch + 防抖由 composables/useAutoDraft.ts 负责，store 不直接 watch 自身
   *   · StatusBar 读 lastDraftSavedAt 显示"已存档 HH:MM"
   *   · null = 当前会话尚未存档过（新打开 / 场景卸载后）
   * ============================================================ */

  /**
   * 最近一次草稿写入时间戳（ms）。
   * null = 本次会话未存档（可能是 localStorage 不可用，也可能是刚打开）。
   */
  const lastDraftSavedAt = ref<number | null>(null)

  /**
   * 写入草稿（由 useAutoDraft 防抖后调用）。
   * 写成功时更新 lastDraftSavedAt，写失败时静默（localStorage 不可用时不更新）。
   */
  function saveDraft(): void {
    if (!sdkSceneUrl.value) return
    const before = lastDraftSavedAt.value
    try {
      saveDraftStorage(sdkSceneUrl.value, sceneConfig.value)
      lastDraftSavedAt.value = Date.now()
    } catch {
      // saveDraftStorage 内部已 catch，此处不应再抛，防御性保留
      lastDraftSavedAt.value = before
    }
  }

  /**
   * 清除草稿。
   * 调用时机：手动导出成功 / 场景卸载 / 用户点击"放弃" / 导入外部 JSON 成功。
   */
  function clearDraft(): void {
    if (!sdkSceneUrl.value) return
    clearDraftStorage(sdkSceneUrl.value)
    lastDraftSavedAt.value = null
  }

  return {
    version,
    sceneId,
    name,
    description,
    bounds,
    objects,
    selectedObjectId,
    selectedObject,
    objectCount,
    selectObject,
    updateObject,
    // 场景管理（历史）
    metaPath,
    sceneMeta,
    isSceneLoaded,
    isLoading,
    loadScene,
    unloadScene,
    // v1.0.0 新增
    sdkSceneUrl,
    recentUrls,
    lastLoadError,
    loadSceneFromUrl,
    pushRecentUrl,
    // v2.0.0 新增 — scene-config 导出数据层
    sceneConfig,
    selectedConfigKey,
    selectConfig,
    selectMetaNode,
    clearSelection,
    collectAllIds,
    updateSceneMeta,
    replaceSceneConfig,
    addFloor,
    updateFloor,
    removeFloor,
    addProp,
    updateProp,
    removeProp,
    canExportConfig,
    configValidationErrors,
    // v6.0.0 新增 — 受控 Snapshot API（撤销/重做基础设施）
    getFloorSnapshot,
    getPropSnapshot,
    insertFloorSnapshot,
    insertPropSnapshot,
    replaceFloorSnapshot,
    replacePropSnapshot,
    removeFloorById,
    removePropById,
    // v3.0.0 新增 — 框选标注流程
    pendingSelection,
    hasPendingSelection,
    setPendingSelection,
    commitPendingAsFloor,
    commitPendingAsProp,
    discardPendingSelection,
    cancelSelectionTick,
    requestCancelSelection,
    cancelSelectionOnly,
    isSelectionDragging,
    setSelectionDragging,
    // v4.0.0 新增 — 创建驱动标注流程（REQ 20260427）
    pendingCreateKind,
    startCreateFloor,
    startCreateProp,
    clearPendingCreateKind,
    // v4.1.0 新增 — 双击行聚焦相机（REQ 20260428）
    focusRequest,
    focusRequestTick,
    focusOnFloor,
    focusOnProp,
    // v4.2.0 新增 — bounds 自动回填（REQ 20260428）
    applyAutoBoundsIfDefault,
    applyAutoBoundsForce,
    recomputeBoundsTick,
    requestRecomputeBounds,
    // v4.2.0 新增 — bounds 计算反馈状态
    lastBoundsComputeStatus,
    setLastBoundsComputeStatus,
    clearLastBoundsComputeStatus,
    // v4.7.0 新增 — Prop 正面朝向指定（facePicking 中间态，REQ 20260508）
    pendingFaceOBB,
    pendingFaceIndex,
    enterFacePicking,
    setPendingFaceIndex,
    confirmPropFace,
    cancelFacePicking,
    clearFacePicking,
    // v7.0.0 新增 — 标注草稿自动存档
    lastDraftSavedAt,
    saveDraft,
    clearDraft,
  }
})
