import type { Command } from '../types/command'

/**
 * 批量命令：按顺序执行多个子命令，undo 时逆序撤销。
 *
 * 事务语义：execute 过程中若某个子命令失败，自动回滚已执行项。
 * 用于：粘贴多个对象、删除多个对象、未来多选移动等场景。
 */
export class BatchCommand implements Command {
  readonly label: string

  constructor(
    private readonly commands: Command[],
    label?: string,
  ) {
    this.label = label ?? `批量操作 ${commands.length} 项`
  }

  execute(): boolean {
    const executed: Command[] = []

    for (const command of this.commands) {
      const ok = command.execute()
      if (!ok) {
        // 回滚已执行项，避免半成功状态
        for (const done of executed.reverse()) {
          if (!done.undo()) {
            console.warn('[BatchCommand] rollback failed for:', done.label)
          }
        }
        return false
      }
      executed.push(command)
    }

    return true
  }

  undo(): boolean {
    const undone: Command[] = []

    // 逆序撤销
    for (const command of [...this.commands].reverse()) {
      const ok = command.undo()
      if (!ok) {
        // 尽量恢复已 undo 的项
        for (const done of undone.reverse()) {
          if (!done.execute()) {
            console.warn('[BatchCommand] recovery failed for:', done.label)
          }
        }
        return false
      }
      undone.push(command)
    }

    return true
  }
}
