<script setup lang="ts">
const props = withDefaults(
  defineProps<{
    modelValue: number
    label?: string
    color?: string
    step?: number
  }>(),
  { step: 0.1 },
)

defineEmits<{
  'update:modelValue': [value: number]
}>()
</script>

<template>
  <div class="flex items-center gap-1">
    <span
      v-if="label"
      class="text-2xs font-mono font-medium shrink-0 w-3 text-center"
      :style="{ color: color || 'var(--color-text-subtle)' }"
    >{{ label }}</span>
    <input
      type="number"
      :value="modelValue"
      :step="step"
      autocomplete="off"
      class="w-full h-[26px] px-2 text-xs font-mono bg-[#242428] text-text-primary
             rounded-md border border-border hover:border-border-strong
             focus:border-accent focus:ring-1 focus:ring-accent/30 focus:outline-none
             transition-all duration-100"
      @input="$emit('update:modelValue', Number(($event.target as HTMLInputElement).value))"
    />
  </div>
</template>
