import * as THREE from 'three'
import type { SelectionAABB } from '../../stores/scene'
import type { FaceIndex } from '../../utils/facePickingMath'

export interface FacePickerOptions {
  camera: THREE.PerspectiveCamera
  scene: THREE.Scene
  domElement: HTMLElement
  /** Raycast 命中切面时回调（左键单击 OBB 某一面）。 */
  onFaceChange: (idx: FaceIndex) => void
  /** 用户确认（Enter / 鼠标双击 / 鼠标右键）。 */
  onConfirm: () => void
  /** 用户取消（Escape）。 */
  onCancel: () => void
}

/**
 * 4 面对照表（tech-design §3.3，CL-3 固化）：
 *   normal  = 本地系法线（仅用于注释，未参与运行时计算 — 几何 transform 已隐含）
 *   axis    = 0 表示 OBB 的 X 半尺寸（halfW）做面宽，1 表示 Z 半尺寸（halfD）做面宽
 *   sign    = +1 / -1，决定面 offset 在主轴上的方向（+halfD / -halfD / +halfW / -halfW）
 *   rotY    = PlaneGeometry（默认法线 +Z）旋转到目标法线所需的绕 Y 弧度
 *
 * faceIndex 对照：
 *   0 (+Z 前): axis=Z, sign=+1, rotY=0
 *   1 (+X 右): axis=X, sign=+1, rotY=-π/2
 *   2 (-Z 后): axis=Z, sign=-1, rotY=+π
 *   3 (-X 左): axis=X, sign=-1, rotY=+π/2
 */
interface FaceConfig {
  axis: 'X' | 'Z'
  sign: 1 | -1
  rotY: number
}
const FACE_CONFIGS: Record<FaceIndex, FaceConfig> = {
  0: { axis: 'Z', sign: 1, rotY: 0 },
  1: { axis: 'X', sign: 1, rotY: -Math.PI / 2 },
  2: { axis: 'Z', sign: -1, rotY: Math.PI },
  3: { axis: 'X', sign: -1, rotY: Math.PI / 2 },
}

/** 高亮面 z-fighting 防御：法线方向外推一个微小距离，防止与 OBB 线框/splat 共面闪烁。 */
const FACE_OFFSET_EPSILON = 0.001

/** 高亮材质参数：与 BoundsHighlightRenderer 字段约定对齐（EV-009/10/13）。 */
const HIGHLIGHT_COLOR = 0x4ade80
const HIGHLIGHT_OPACITY = 0.35 // v1.2.0：从 0.25 提到 0.35，面正对相机时薄薄一片也易感知

/** 浮顶 renderOrder：高于 BoundsHighlightRenderer 的 1002，让高亮面/箭头永远显示在最上层。 */
const FACE_RENDER_ORDER = 1003

/**
 * 正面箭头指示器尺寸比例（相对 OBB 最短水平半尺寸）。
 * 0.25 = 箭头半径约为 OBB 宽度的 1/4，足够在任意视角下醒目，又不会压到 Gizmo/操作区。
 */
const ARROW_SCALE = 0.25

export class FacePicker {
  private camera: THREE.PerspectiveCamera
  private scene: THREE.Scene
  private domElement: HTMLElement
  private onFaceChange: (idx: FaceIndex) => void
  private onConfirm: () => void
  private onCancel: () => void

  /** 4 面 mesh 的容器 group，外层应用 OBB 的 position/rotation.y。 */
  private group: THREE.Group | null = null
  /** 4 个面 mesh，按 FaceIndex 索引（0..3）。 */
  private faceMeshes: THREE.Mesh[] | null = null
  /** 当前高亮的面索引。 */
  private currentFaceIndex: FaceIndex | null = null
  /** 当前 OBB 快照（仅在 show 时写入；同 ADR-002）。 */
  private currentOBB: SelectionAABB | null = null

  /**
   * 复用材质（4 idle + 1 active）—— mesh 切换通过替换 material 引用，不 dispose。
   * 一份 active 共享给"当前高亮面"那一个 mesh；切面时仅把该 mesh 的 material
   * 还原成对应 idleMat，新的 active mesh 改用 activeMat。
   */
  private idleMaterials: THREE.MeshBasicMaterial[] | null = null
  private activeMaterial: THREE.MeshBasicMaterial | null = null

  /** 复用 raycaster 实例。 */
  private raycaster: THREE.Raycaster

  // 事件 bound 引用
  private boundOnPointerDown: ((e: PointerEvent) => void) | null = null
  private boundOnDblClick: ((e: MouseEvent) => void) | null = null
  private boundOnContextMenu: ((e: MouseEvent) => void) | null = null
  private boundOnKeyDown: ((e: KeyboardEvent) => void) | null = null

  constructor(options: FacePickerOptions) {
    this.camera = options.camera
    this.scene = options.scene
    this.domElement = options.domElement
    this.onFaceChange = options.onFaceChange
    this.onConfirm = options.onConfirm
    this.onCancel = options.onCancel
    this.raycaster = new THREE.Raycaster()
  }

  /**
   * 创建 4 个面 mesh + 高亮初始面 + 绑定事件。
   * 重复调用：先 hide() 清空再重建（防御性，理论上 facePicking 期间 OBB 不变）。
   */
  show(obb: SelectionAABB, initialFaceIndex: FaceIndex): void {
    this.hide() // 幂等防御

    this.currentOBB = obb
    this.currentFaceIndex = initialFaceIndex

    const halfW = (obb.maxX - obb.minX) / 2
    const halfD = (obb.maxZ - obb.minZ) / 2
    const centerX = (obb.minX + obb.maxX) / 2
    const centerZ = (obb.minZ + obb.maxZ) / 2

    // Y 维度对齐 BoundsHighlightRenderer（EV-012 同源）
    const yBase = obb.minY ?? 0.02
    const yTop = obb.maxY ?? yBase + 1
    const yMid = (yBase + yTop) / 2
    const faceHeight = Math.max(yTop - yBase, 0.001)

    this.group = new THREE.Group()
    this.group.position.set(centerX, 0, centerZ)
    this.group.rotation.y = obb.rotationY ?? 0
    // v1.2.0：group 本身不设 renderOrder，具体由各 child mesh 自己决定（高亮面 / 箭头走浮顶 1003）

    // 4 idle 材质 + 1 active 材质（v1.2.0 浮顶策略：depthTest:false + renderOrder:1003）
    //   EV-010 推荐路径：用材质 depthTest:false 直接浮顶，不要用 clearDepth/onBeforeRender 副作用
    //   与 BoundsHighlightRenderer（v1.1.3 depthTest:true 追求立体感）的差异：本场景"看不见则失效"
    //   （EV-014 死按钮反模式），必须保证 4 面任意视角可见可点
    this.idleMaterials = [0, 1, 2, 3].map(
      () =>
        new THREE.MeshBasicMaterial({
          color: 0x000000,
          transparent: true,
          opacity: 0, // 不可见但 raycast 仍命中（RISK-DA007）
          depthTest: false, // v1.2.0：浮顶，确保被 splat 遮挡时仍能命中
          depthWrite: false,
          side: THREE.DoubleSide,
        }),
    )
    this.activeMaterial = new THREE.MeshBasicMaterial({
      color: HIGHLIGHT_COLOR,
      transparent: true,
      opacity: HIGHLIGHT_OPACITY,
      depthTest: false, // v1.2.0：浮顶，EV-010 正解
      depthWrite: false,
      side: THREE.DoubleSide,
    })

    this.faceMeshes = ([0, 1, 2, 3] as FaceIndex[]).map((idx) => {
      const cfg = FACE_CONFIGS[idx]
      // 面尺寸：法线轴对应的"另一个"半尺寸做面宽
      // axis='Z' (法线 ±Z): 面宽 = 2*halfW (X 方向)
      // axis='X' (法线 ±X): 面宽 = 2*halfD (Z 方向)
      const faceWidth = cfg.axis === 'Z' ? halfW * 2 : halfD * 2
      const geom = new THREE.PlaneGeometry(faceWidth, faceHeight)

      // 选择材质：当前高亮面用 activeMaterial，其它用对应 idleMaterial
      const mat =
        idx === initialFaceIndex
          ? this.activeMaterial!
          : this.idleMaterials![idx]
      const mesh = new THREE.Mesh(geom, mat)
      mesh.name = `face-picker-face-${idx}`
      mesh.renderOrder = FACE_RENDER_ORDER // v1.2.0 浮顶
      mesh.userData.faceIndex = idx as FaceIndex // raycast 命中后取索引

      // 位置：face 中心
      // axis='Z' → offset 在 ±Z 方向（halfD + ε）；axis='X' → offset 在 ±X 方向（halfW + ε）
      if (cfg.axis === 'Z') {
        mesh.position.set(0, yMid, cfg.sign * (halfD + FACE_OFFSET_EPSILON))
      } else {
        mesh.position.set(cfg.sign * (halfW + FACE_OFFSET_EPSILON), yMid, 0)
      }
      // 旋转：PlaneGeometry 默认法线 +Z，rotateY 到目标法线
      mesh.rotation.y = cfg.rotY

      this.group!.add(mesh)
      return mesh
    })

    this.scene.add(this.group)

    // 绑定事件（生命周期与 FacePicker 实例严格对齐 — 见 RISK-DA006）
    this.bindEvents()
  }

  /**
   * 增量更新：仅切换高亮面，不重建 mesh（性能 + 视觉无闪烁）。
   * 通过 material 引用替换实现，不动 geometry / position / rotation。
   */
  setFaceIndex(idx: FaceIndex): void {
    if (
      !this.faceMeshes ||
      !this.idleMaterials ||
      !this.activeMaterial ||
      idx === this.currentFaceIndex
    )
      return

    // 旧高亮面恢复 idle
    if (this.currentFaceIndex !== null) {
      this.faceMeshes[this.currentFaceIndex].material =
        this.idleMaterials[this.currentFaceIndex]
    }
    // 新面应用 active
    this.faceMeshes[idx].material = this.activeMaterial
    this.currentFaceIndex = idx
  }

  /**
   * 隐藏 + 解绑 + dispose 资源；幂等（重复调用安全）。
   */
  hide(): void {
    this.unbindEvents()

    if (this.group) {
      // dispose geometry（材质单独管理，不在循环里 dispose 防止重复）
      for (const mesh of this.group.children) {
        const m = mesh as THREE.Mesh
        m.geometry?.dispose()
      }
      this.scene.remove(this.group)
      this.group = null
    }

    this.idleMaterials?.forEach((m) => m.dispose())
    this.activeMaterial?.dispose()
    this.idleMaterials = null
    this.activeMaterial = null

    this.faceMeshes = null
    this.currentFaceIndex = null
    this.currentOBB = null
  }

  /** dispose 别名，对齐 SelectionManager / BoundsHighlightRenderer 风格。 */
  dispose(): void {
    this.hide()
  }

  /* ============================================================
   * 事件层 (B-05)
   * ============================================================ */

  private bindEvents(): void {
    this.boundOnPointerDown = this.onPointerDown.bind(this)
    this.boundOnDblClick = this.onDblClick.bind(this)
    this.boundOnContextMenu = this.onContextMenu.bind(this)
    this.boundOnKeyDown = this.onKeyDown.bind(this)

    this.domElement.addEventListener('pointerdown', this.boundOnPointerDown)
    this.domElement.addEventListener('dblclick', this.boundOnDblClick)
    this.domElement.addEventListener('contextmenu', this.boundOnContextMenu)
    // keydown 必须 capture 阶段：抢在 useTransformShortcuts 等其它 window keydown 之前消费 Enter/Esc
    window.addEventListener('keydown', this.boundOnKeyDown, true)
  }

  private unbindEvents(): void {
    if (this.boundOnPointerDown) {
      this.domElement.removeEventListener('pointerdown', this.boundOnPointerDown)
      this.boundOnPointerDown = null
    }
    if (this.boundOnDblClick) {
      this.domElement.removeEventListener('dblclick', this.boundOnDblClick)
      this.boundOnDblClick = null
    }
    if (this.boundOnContextMenu) {
      this.domElement.removeEventListener('contextmenu', this.boundOnContextMenu)
      this.boundOnContextMenu = null
    }
    if (this.boundOnKeyDown) {
      window.removeEventListener('keydown', this.boundOnKeyDown, true)
      this.boundOnKeyDown = null
    }
  }

  /**
   * 左键单击：raycast 命中某面 → onFaceChange；命中空白 → 静默（CL-1）。
   * 拖动：本 handler 仅在 pointerdown 触发，不监听 pointermove/pointerup → 拖动天然无效。
   */
  private onPointerDown(e: PointerEvent): void {
    // 仅左键
    if (e.button !== 0) return
    if (!this.faceMeshes) return

    const ndc = this.toNDC(e)
    this.raycaster.setFromCamera(ndc, this.camera)
    const intersects = this.raycaster.intersectObjects(this.faceMeshes, false)
    if (intersects.length === 0) return // 空白处：静默

    const hit = intersects[0].object as THREE.Mesh
    const idx = hit.userData.faceIndex as FaceIndex | undefined
    if (idx === undefined) return

    e.preventDefault()
    e.stopPropagation()
    this.onFaceChange(idx)
  }

  /** 双击：直接 confirm（无 raycast 校验，PRD §3.4）。 */
  private onDblClick(e: MouseEvent): void {
    e.preventDefault()
    e.stopPropagation()
    this.onConfirm()
  }

  /** 右键：直接 confirm + 阻止浏览器右键菜单（PRD §3.4）。 */
  private onContextMenu(e: MouseEvent): void {
    e.preventDefault()
    e.stopPropagation()
    this.onConfirm()
  }

  /**
   * 键盘快捷键：
   *   - Escape：取消
   *   - ArrowLeft / ArrowRight：循环切面（v1.3.0）
   * 确认操作由 dblclick / contextmenu 承担，不再监听 Enter。
   * 使用 e.code 物理键位（EV-006）；capture 阶段 + stopPropagation 抢占（RISK-DA006）。
   */
  private onKeyDown(e: KeyboardEvent): void {
    if (e.code === 'Escape') {
      e.preventDefault()
      e.stopPropagation()
      this.onCancel()
    } else if (e.code === 'ArrowLeft' || e.code === 'ArrowRight') {
      e.preventDefault()
      e.stopPropagation()
      if (this.currentFaceIndex === null) return
      const delta = e.code === 'ArrowRight' ? 1 : 3 // +1 顺时针, +3 等效于 -1 mod 4
      const next = ((this.currentFaceIndex + delta) % 4) as FaceIndex
      this.onFaceChange(next)
    }
  }

  /** 鼠标坐标 → NDC（[-1, 1]）。 */
  private toNDC(e: PointerEvent | MouseEvent): THREE.Vector2 {
    const rect = this.domElement.getBoundingClientRect()
    const x = ((e.clientX - rect.left) / rect.width) * 2 - 1
    const y = -(((e.clientY - rect.top) / rect.height) * 2 - 1)
    return new THREE.Vector2(x, y)
  }
}
