<!--
  OpenSceneUrlDialog — 打开场景 URL 对话框

  - 受控组件（v-model:visible）
  - 输入 meta.json URL + 最近使用列表 + 加载中态 + 分类错误提示
  - 调用链：confirm → store.loadSceneFromUrl → await nextTick → 检查 store.lastLoadError

  @changelog
  | 版本   | 变更说明                                                 | 关联                                                                 |
  | v1.0.0 | 初始实现：URL 输入对话框 + 最近列表 + 错误分类展示        | REQ: 20260422-splat-studio-meta加载 TECH: 04_design_tech-design.md §3.4 |
  | v1.1.0 | 最近使用列表的长 URL 改为「中间省略」展示：保留协议/域名前缀和文件名后缀，中间用 … 省略，避免尾部被 truncate 后看不清是哪个模型 | EVOLVE: 用户反馈尾部 truncate 看不见文件名 |
  | v1.2.0 | 最近使用列表项支持「双击直接加载」：单击仅回填 URL（保留之前的预览/编辑选项），双击 = 单击回填 + 立即触发 onConfirm，省去再点确定按钮的步骤 | EVOLVE: 用户反馈交互冗余 |

  @author v_djlzhou
-->
<script setup lang="ts">
import { ref, watch, nextTick } from 'vue'
import { useSceneStore, formatLoadSceneError } from '../../stores/scene'

const props = defineProps<{
  visible: boolean
}>()

const emit = defineEmits<{
  (e: 'update:visible', value: boolean): void
}>()

const sceneStore = useSceneStore()

const url = ref('')
const errorMsg = ref('')
const loading = ref(false)

// 重置表单（对话框打开时清空上次状态）
watch(
  () => props.visible,
  (v) => {
    if (v) {
      url.value = ''
      errorMsg.value = ''
      loading.value = false
    }
  },
)

function close() {
  if (loading.value) return // 加载中不允许关闭
  emit('update:visible', false)
}

function pickRecent(u: string) {
  if (loading.value) return
  url.value = u
  errorMsg.value = ''
}

/**
 * 双击最近使用项：回填 URL 并立即触发加载，省去用户再点「确定」的步骤。
 * 注意：dblclick 会先触发两次 click，pickRecent 已幂等（只是回填同一个 URL），无副作用。
 */
function pickRecentAndConfirm(u: string) {
  if (loading.value) return
  pickRecent(u)
  onConfirm()
}

/**
 * 将 URL 切成「头段 + 尾段」用于中间省略展示。
 * - 尾段固定取最后 TAIL_LEN 个字符（一般够覆盖文件名 + 上一级目录）
 * - 头段 = 剩余前缀，由 CSS truncate 在前段省略
 * - 短 URL 直接整段当头部，尾段为空（避免无意义切分）
 */
const TAIL_LEN = 24
function splitForMiddleEllipsis(u: string): { head: string; tail: string } {
  if (u.length <= TAIL_LEN + 8) return { head: u, tail: '' }
  return {
    head: u.slice(0, u.length - TAIL_LEN),
    tail: u.slice(u.length - TAIL_LEN),
  }
}





async function onConfirm() {
  const v = url.value.trim()
  if (!v) {
    errorMsg.value = '请输入 meta.json URL'
    return
  }
  errorMsg.value = ''
  loading.value = true
  try {
    await sceneStore.loadSceneFromUrl(v)
    // 等一帧让 Viewport 的 watch 跑完 SDK init（tech-design §3.4.3）
    await nextTick()
    // 再等一帧确保 async watch 回调完成
    await new Promise((r) => setTimeout(r, 0))

    if (sceneStore.lastLoadError) {
      errorMsg.value = formatLoadSceneError(sceneStore.lastLoadError)
      sceneStore.lastLoadError = null
      return
    }
    // 成功：关闭对话框
    emit('update:visible', false)
  } catch (e) {
    // Store action 内抛出的 LoadSceneError
    errorMsg.value = formatLoadSceneError(e)
    // action 抛错时 store 状态未被修改（原子提交语义），不需要回滚
  } finally {
    loading.value = false
  }
}

function onKeydown(e: KeyboardEvent) {
  if (e.key === 'Escape') close()
  if (e.key === 'Enter' && !e.shiftKey && !loading.value) {
    e.preventDefault()
    onConfirm()
  }
}
</script>

<template>
  <Teleport to="body">
    <div
      v-if="visible"
      class="fixed inset-0 z-[1000] flex items-center justify-center bg-black/50 backdrop-blur-sm"
      @click.self="close"
      @keydown="onKeydown"
    >
      <div
        class="w-[520px] max-w-[90vw] bg-[#242428] border border-border-strong rounded-lg shadow-dropdown
               flex flex-col overflow-hidden"
        role="dialog"
        aria-modal="true"
        data-tour="open-scene-dialog"
      >
        <!-- Header -->
        <div class="flex items-center justify-between h-10 px-4 border-b border-border">
          <span class="text-sm font-semibold text-text-primary">打开场景 URL</span>
          <button
            class="w-6 h-6 flex items-center justify-center text-text-subtle hover:text-text-primary
                   hover:bg-bg-hover rounded transition-colors cursor-pointer"
            :disabled="loading"
            @click="close"
            aria-label="关闭"
          >
            ✕
          </button>
        </div>

        <!-- Body -->
        <div class="flex flex-col gap-3 p-4">
          <label class="flex flex-col gap-1">
            <span class="text-xs text-text-secondary">meta.json URL</span>
            <input
              v-model="url"
              type="text"
              :disabled="loading"
              placeholder="https://cdn.example.com/xxx/meta.json"
              class="h-8 px-2 text-xs bg-[#1a1a1d] border border-border rounded
                     text-text-primary placeholder:text-text-subtle
                     focus:border-accent outline-none transition-colors
                     disabled:opacity-60"
              @keydown="onKeydown"
            />
          </label>

          <!-- 错误提示 -->
          <div
            v-if="errorMsg"
            class="text-xs text-red-400 bg-red-500/10 border border-red-500/30 rounded px-2 py-1.5"
          >
            ⚠ {{ errorMsg }}
          </div>

          <!-- 最近使用 -->
          <div v-if="sceneStore.recentUrls.length > 0" class="flex flex-col gap-1">
            <span class="text-xs text-text-secondary">最近使用</span>
            <div class="max-h-[180px] overflow-y-auto flex flex-col gap-0.5">
              <button
                v-for="u in sceneStore.recentUrls"
                :key="u"
                class="flex items-center text-left text-xs text-text-primary px-2 py-1.5 rounded
                       hover:bg-bg-hover active:bg-bg-active transition-colors cursor-pointer
                       disabled:opacity-60 disabled:cursor-not-allowed w-full min-w-0"
                :disabled="loading"
                :title="`${u}\n（双击直接加载）`"
                @click="pickRecent(u)"
                @dblclick="pickRecentAndConfirm(u)"
              >
                <!-- 中间省略：头段自动 truncate（CSS 自动产生 …）+ 尾段固定显示文件名 -->
                <span class="truncate min-w-0 flex-1">{{ splitForMiddleEllipsis(u).head }}</span>
                <span
                  v-if="splitForMiddleEllipsis(u).tail"
                  class="flex-shrink-0 whitespace-nowrap"
                >{{ splitForMiddleEllipsis(u).tail }}</span>
              </button>
            </div>
          </div>
        </div>

        <!-- Footer -->
        <div class="flex items-center justify-end gap-2 h-12 px-4 border-t border-border bg-[#1a1a1d]">
          <button
            class="h-7 px-3 text-xs text-text-primary bg-transparent border border-border rounded
                   hover:bg-bg-hover transition-colors cursor-pointer
                   disabled:opacity-60 disabled:cursor-not-allowed"
            :disabled="loading"
            @click="close"
          >
            取消
          </button>
          <button
            class="h-7 px-3 text-xs text-white bg-accent rounded hover:bg-accent-hover
                   transition-colors cursor-pointer font-medium
                   disabled:opacity-60 disabled:cursor-not-allowed"
            :disabled="loading || !url.trim()"
            @click="onConfirm"
          >
            {{ loading ? '加载中...' : '确定' }}
          </button>
        </div>
      </div>
    </div>
  </Teleport>
</template>
